2739	    fn prefetch_worktree_default_branch(
2740	        &mut self,
2741	        key: &ProjectGroupKey,
2742	        workspace: &Entity<Workspace>,
2743	        cx: &mut Context<Self>,
2744	    ) {
2745	        // Presence of the key means the group is already pending or resolved. The
2746	        // no-repository case is deliberately not inserted so it retries on a
2747	        // later rebuild once the repository has finished loading.
2748	        if self.worktree_default_branches.contains_key(key) {
2749	            return;
2750	        }
2751	        let Some(repository) = workspace.read(cx).project().read(cx).active_repository(cx) else {
2752	            return;
2753	        };
2754	        let request = repository.update(cx, |repository, _| repository.default_branch(true));
2755	        self.worktree_default_branches
2756	            .insert(key.clone(), DefaultBranchCache::Pending);
2757	        let key = key.clone();
2758	        cx.spawn(async move |this, cx| {
2759	            let default_branch = request.await.ok().and_then(Result::ok).flatten();
2760	            let parsed = default_branch.as_deref().and_then(RemoteBranchName::parse);
2761	            this.update(cx, |sidebar, cx| {
2762	                sidebar
2763	                    .worktree_default_branches
2764	                    .insert(key, DefaultBranchCache::Resolved(parsed));
2765	                cx.notify();
2766	            })
2767	            .ok();
2768	        })
2769	        .detach();
