                .read_with(cx, |mw, _| {
                    let keys = mw.project_group_keys();
                    let index = keys.iter().position(|k| k == &project_group_key);
                    (index, keys.len())
                })
                .unwrap_or((None, 0));
            let show_reorder_entries = total_groups >= 2;
